begin;
do $$declare n text;f record;begin
 if to_regclass('public.ac_dce_work_items')is null or to_regclass('public.ac_dce_attachment_receipts')is null then raise exception 'DCE_R4_REQUIRED';end if;
 foreach n in array array['ac_dce_editions','ac_dce_assessment_attempts','ac_dce_certificate_requests','ac_dce_certificate_history']loop
 if to_regclass('public.'||n)is not null and obj_description(to_regclass('public.'||n),'pg_class')is distinct from'ANGELCARE_DCE_AUTONOMOUS_R5'then raise exception 'UNRELATED_TABLE: %',n;end if;end loop;
 for f in select oid,proname from pg_proc where pronamespace='public'::regnamespace and proname like 'ac_dce_r5_%'loop if obj_description(f.oid,'pg_proc')is distinct from'ANGELCARE_DCE_AUTONOMOUS_R5'then raise exception 'UNRELATED_FUNCTION: %',f.proname;end if;end loop;
end $$;
create table if not exists public.ac_dce_editions(record_id uuid not null references ac_dce_records on delete restrict,locale text not null check(locale in('ar','fr','en')),state text not null check(state in('draft','review','approved')),definition_hash text not null check(definition_hash~'^[a-f0-9]{64}$'),definition jsonb not null,reviewed_by text,approved_by text,active_release_id uuid references ac_dce_releases on delete restrict,revision int not null default 1,updated_at timestamptz not null default now(),tenant_id text,territory_id text,primary key(record_id,locale));
create table if not exists public.ac_dce_assessment_attempts(id uuid primary key,course_id uuid not null references ac_dce_records,course_release_id uuid not null references ac_dce_releases,assessment_release_id uuid references ac_dce_releases,locale text not null check(locale in('ar','fr','en')),subject_hash text not null check(subject_hash~'^[a-f0-9]{64}$'),evidence jsonb not null,evidence_level text not null check(evidence_level in('manual_review','server_assessment')),completed boolean not null,score numeric check(score between 0 and 100),created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval'30 days'),tenant_id text,territory_id text);
create table if not exists public.ac_dce_certificate_requests(id uuid primary key default gen_random_uuid(),reference text not null unique,course_id uuid not null references ac_dce_records,release_id uuid not null references ac_dce_releases,attempt_id uuid not null unique references ac_dce_assessment_attempts,locale text not null check(locale in('ar','fr','en')),subject_hash text not null,course_title text not null,learner_name text not null,requester_name text not null,email text not null,phone text not null default'',contact_locale text not null check(contact_locale in('ar','fr','en')),status text not null default'new'check(status in('new','review','awaiting_information','approved','issued','rejected','cancelled','closed')),assigned_to text,due_at timestamptz,revision int not null default 1,evidence jsonb not null,policy jsonb not null,data jsonb not null default'{}',issued_at timestamptz,issued_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),tenant_id text,territory_id text);
create table if not exists public.ac_dce_certificate_history(id uuid primary key default gen_random_uuid(),request_id uuid not null references ac_dce_certificate_requests on delete restrict,actor_id text not null,action text not null,data jsonb not null default'{}',created_at timestamptz not null default now());
create index if not exists ac_dce_r5_certificate_queue on ac_dce_certificate_requests(tenant_id,territory_id,status,created_at desc,id);
create index if not exists ac_dce_r5_certificate_followup on ac_dce_certificate_requests(assigned_to,due_at);
create index if not exists ac_dce_r5_history on ac_dce_certificate_history(request_id,created_at desc,id);
create index if not exists ac_dce_r5_attempt_subject on ac_dce_assessment_attempts(course_release_id,subject_hash);
create or replace function public.ac_dce_r5_edition(p_actor text,p_tenant text,p_territory text,p_request uuid,p_hash text,p_id uuid,p_revision int,p_locale text,p_action text,p_definition jsonb,p_definition_hash text,p_manifest jsonb default'{}',p_validation jsonb default'{}',p_schedule timestamptz default null,p_release uuid default null)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare r ac_dce_records;e ac_dce_editions;z ac_dce_releases;c ac_dce_commands;reply jsonb;policy jsonb;begin
 if nullif(p_actor,'')is null or p_locale not in('ar','fr','en')or p_definition_hash!~'^[a-f0-9]{64}$'then raise exception'INVALID_EDITION_COMMAND';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor||p_request::text,0));select *into c from ac_dce_commands where actor_id=p_actor and request_id=p_request;
 if found then if c.input_hash<>p_hash then raise exception'IDEMPOTENCY_CONFLICT';end if;return c.response;end if;
 select *into r from ac_dce_records where id=p_id and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory for update;
 if not found or r.kind not in('experience','content','template','bundle')then raise exception'NOT_FOUND';end if;if r.revision<>p_revision then raise exception'REVISION_CONFLICT';end if;
 select *into e from ac_dce_editions where record_id=p_id and locale=p_locale for update;
 if p_action in('review','approve','release','schedule')and(coalesce((p_validation->>'valid')::boolean,false)is not true or length(coalesce(p_definition->>'title',''))=0)then raise exception'EDITION_READINESS_REQUIRED';end if;
 if p_action='review'then
 insert into ac_dce_editions(record_id,locale,state,definition_hash,definition,reviewed_by,tenant_id,territory_id)values(p_id,p_locale,'review',p_definition_hash,p_definition,p_actor,p_tenant,p_territory)on conflict(record_id,locale)do update set state='review',definition_hash=excluded.definition_hash,definition=excluded.definition,reviewed_by=p_actor,approved_by=null,revision=ac_dce_editions.revision+1,updated_at=now()returning *into e;
 elsif p_action='approve'then
 if e.state is distinct from'review'or e.definition_hash is distinct from p_definition_hash then raise exception'EDITION_REVIEW_REQUIRED';end if;
 if exists(select 1 from ac_dce_work_items w where w.record_id=p_id and w.kind='task'and w.status not in('done','cancelled')and coalesce((w.data->>'blocking')::boolean,false)and(coalesce(w.data->>'locale','')=''or w.data->>'locale'=p_locale))then raise exception'EDITORIAL_TASKS_BLOCKED';end if;
 select data into policy from ac_dce_work_items where kind='editorial_policy'and status='active'and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory order by updated_at desc,id limit 1;
 if coalesce((policy->>'independentReview')::boolean,false)and(e.reviewed_by=p_actor or r.updated_by=p_actor)then raise exception'INDEPENDENT_REVIEW_REQUIRED';end if;
 update ac_dce_editions set state='approved',approved_by=p_actor,revision=revision+1,updated_at=now()where record_id=p_id and locale=p_locale returning *into e;
 elsif p_action in('release','schedule')then
 if e.state is distinct from'approved'or e.definition_hash is distinct from p_definition_hash or e.definition is distinct from p_definition then raise exception'EDITION_APPROVAL_REQUIRED';end if;
 if p_action='schedule'and(p_schedule is null or p_schedule<=now())then raise exception'FUTURE_DATE_REQUIRED';end if;
 if p_manifest->>'editionLocale'is distinct from p_locale or p_manifest->>'editionHash'is distinct from p_definition_hash then raise exception'EDITION_MANIFEST_REQUIRED';end if;
 insert into ac_dce_releases(record_id,revision,snapshot,manifest,validation,state,scheduled_at,published_at,actor_id,tenant_id,territory_id)values(p_id,r.revision,to_jsonb(r),p_manifest,p_validation,case when p_action='schedule'then'scheduled'else'published'end,p_schedule,case when p_action='release'then now()end,p_actor,p_tenant,p_territory)returning *into z;
 if p_action='release'then update ac_dce_editions set active_release_id=z.id,revision=revision+1,updated_at=now()where record_id=p_id and locale=p_locale returning *into e;update ac_dce_records set published_release_id=coalesce(published_release_id,z.id)where id=p_id;end if;
 elsif p_action in('withdraw','restore','cancel','reschedule','due','fail')then
 select *into z from ac_dce_releases where id=p_release and record_id=p_id and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory for update;
 if not found or z.manifest->>'editionLocale'is distinct from p_locale then raise exception'EDITION_RELEASE_NOT_FOUND';end if;
 if p_action='withdraw'then
 if e.active_release_id is distinct from z.id or z.state<>'published'then raise exception'NOT_CURRENT_RELEASE';end if;update ac_dce_releases set state='withdrawn'where id=z.id returning *into z;update ac_dce_editions set active_release_id=null,revision=revision+1,updated_at=now()where record_id=p_id and locale=p_locale returning *into e;
 elsif p_action='restore'then
 if z.state not in('published','withdrawn')or coalesce((p_validation->>'valid')::boolean,false)is not true then raise exception'RESTORE_BLOCKED';end if;update ac_dce_releases set state='published',published_at=now()where id=z.id returning *into z;update ac_dce_editions set active_release_id=z.id,revision=revision+1,updated_at=now()where record_id=p_id and locale=p_locale returning *into e;
 elsif p_action='reschedule'then
 if z.state<>'scheduled'or p_schedule is null or p_schedule<=now()or p_definition_hash is distinct from z.manifest->>'editionHash'then raise exception'RESCHEDULE_BLOCKED';end if;update ac_dce_releases set scheduled_at=p_schedule where id=z.id returning *into z;
 elsif p_action='cancel'then
 if z.state<>'scheduled'then raise exception'NOT_SCHEDULED';end if;update ac_dce_releases set state='cancelled'where id=z.id returning *into z;
 elsif p_action='fail'then
 if z.state<>'scheduled'then raise exception'NOT_SCHEDULED';end if;update ac_dce_releases set state='failed',error='Edition source or dependencies changed; previous live edition preserved.'where id=z.id returning *into z;
 else
 if z.state<>'scheduled'or z.scheduled_at>now()then raise exception'NOT_DUE';end if;if e.definition_hash is distinct from z.manifest->>'editionHash'or p_definition_hash is distinct from z.manifest->>'editionHash'or coalesce((p_validation->>'valid')::boolean,false)is not true then raise exception'EDITION_CHANGED';end if;
 update ac_dce_releases set state='published',published_at=now()where id=z.id returning *into z;update ac_dce_editions set active_release_id=z.id,revision=revision+1,updated_at=now()where record_id=p_id and locale=p_locale returning *into e;
 end if;
 update ac_dce_records set published_release_id=(select active_release_id from ac_dce_editions where record_id=p_id and active_release_id is not null order by locale limit 1)where id=p_id and(published_release_id=z.id or published_release_id is null);
 else raise exception'UNKNOWN_EDITION_ACTION';end if;
 insert into ac_dce_events(channel,action,record_id,actor_id,request_id,data,tenant_id,territory_id)values('admin','edition_'||p_action,p_id,p_actor,p_request,jsonb_build_object('locale',p_locale,'releaseId',z.id,'definitionHash',p_definition_hash),p_tenant,p_territory);
 reply:=jsonb_build_object('edition',to_jsonb(e),'release',case when z.id is not null then to_jsonb(z)else null end,'receipt',p_request);insert into ac_dce_commands values(p_request,p_actor,p_hash,reply,now());return reply;
end $$;
create or replace function public.ac_dce_r5_inventory(p_tenant text,p_territory text,p_locale text,p_state text default'all',p_family text default'',p_search text default'',p_page int default 1)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare reply jsonb;begin
 if p_locale not in('ar','fr','en')or p_state not in('all','live','draft','absent')or p_page<1 then raise exception'INVALID_INVENTORY';end if;
 with source as(select r.*,coalesce(r.data->>'defaultLocale','en')=p_locale or length(coalesce(r.data->'locales'->p_locale->>'title',''))>0 present,e.active_release_id,e.state edition_state,e.definition_hash from ac_dce_records r left join ac_dce_editions e on e.record_id=r.id and e.locale=p_locale where r.kind in('experience','content','template','bundle')and r.lifecycle<>'archived'and r.tenant_id is not distinct from p_tenant and r.territory_id is not distinct from p_territory and(p_family=''or r.family=p_family)and(p_search=''or r.title ilike '%'||p_search||'%'or r.key ilike '%'||p_search||'%')),matching as(select *from source where p_state='all'or p_state='live'and active_release_id is not null or p_state='draft'and present and active_release_id is null or p_state='absent'and not present),paged as(select *from matching order by updated_at desc,id limit 30 offset(p_page-1)*30)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(p))from paged p),'[]'),'total',(select count(*)from matching),'page',p_page,'pageSize',30,'complete',true)into reply;return reply;
end $$;
create or replace function public.ac_dce_r5_attempt(p_row jsonb,p_limit int)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare a ac_dce_assessment_attempts;z ac_dce_releases;n int;begin
 if p_row->>'subject_hash'!~'^[a-f0-9]{64}$'or p_limit not between 1 and 50 then raise exception'INVALID_ATTEMPT';end if;
 perform pg_advisory_xact_lock(hashtextextended((p_row->>'course_release_id')||':'||(p_row->>'subject_hash'),0));select *into a from ac_dce_assessment_attempts where id=(p_row->>'id')::uuid;
 if found then if a.subject_hash is distinct from p_row->>'subject_hash'or a.evidence->>'inputHash'is distinct from p_row->'evidence'->>'inputHash'then raise exception'ATTEMPT_IDEMPOTENCY_CONFLICT';end if;if a.expires_at<=now()then raise exception'ATTEMPT_EXPIRED';end if;return to_jsonb(a);end if;
 select *into z from ac_dce_releases where id=(p_row->>'course_release_id')::uuid and state='published';if not found or z.record_id::text is distinct from p_row->>'course_id'or z.tenant_id is distinct from nullif(p_row->>'tenant_id','')or z.territory_id is distinct from nullif(p_row->>'territory_id','')or not exists(select 1 from ac_dce_editions where record_id=z.record_id and locale=p_row->>'locale'and active_release_id=z.id)then raise exception'COURSE_RELEASE_NOT_ACTIVE';end if;
 select count(*)into n from ac_dce_assessment_attempts where course_release_id=z.id and subject_hash=p_row->>'subject_hash';if n>=p_limit then raise exception'ATTEMPT_LIMIT_REQUIRED';end if;
 insert into ac_dce_assessment_attempts(id,course_id,course_release_id,assessment_release_id,locale,subject_hash,evidence,evidence_level,completed,score,tenant_id,territory_id)values((p_row->>'id')::uuid,z.record_id,z.id,nullif(p_row->>'assessment_release_id','')::uuid,p_row->>'locale',p_row->>'subject_hash',p_row->'evidence',p_row->>'evidence_level',(p_row->>'completed')::boolean,(p_row->>'score')::numeric,z.tenant_id,z.territory_id)returning *into a;return to_jsonb(a);
end $$;
create or replace function public.ac_dce_r5_certificate_receive(p_actor text,p_tenant text,p_territory text,p_request uuid,p_hash text,p_attempt uuid,p_subject_hash text,p_details jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare a ac_dce_assessment_attempts;r ac_dce_certificate_requests;z ac_dce_releases;c ac_dce_commands;policy jsonb;reply jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended(p_actor||p_request::text,0));select *into c from ac_dce_commands where actor_id=p_actor and request_id=p_request;if found then if c.input_hash<>p_hash then raise exception'IDEMPOTENCY_CONFLICT';end if;return c.response;end if;
 select *into a from ac_dce_assessment_attempts where id=p_attempt and subject_hash=p_subject_hash and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory for update;if not found or a.expires_at<=now()then raise exception'ATTEMPT_NOT_FOUND';end if;
 select *into z from ac_dce_releases where id=a.course_release_id and state='published';if not found or not exists(select 1 from ac_dce_editions where record_id=a.course_id and locale=a.locale and active_release_id=z.id)then raise exception'COURSE_RELEASE_NOT_ACTIVE';end if;policy:=z.manifest->'certificate';
 if coalesce((policy->>'enabled')::boolean,false)is not true or(coalesce(policy->'locales','[]')?a.locale)is not true then raise exception'CERTIFICATES_DISABLED';end if;
 if coalesce((policy->>'requiresCompletion')::boolean,true)and not a.completed then raise exception'COMPLETION_REQUIRED';end if;
 if coalesce((policy->>'minimumScore')::numeric,0)>0 and(a.score is null or a.score<(policy->>'minimumScore')::numeric)then raise exception'SCORE_REQUIRED';end if;
 if policy->>'evidence'='server_assessment'and a.evidence_level<>'server_assessment'then raise exception'VERIFIED_ASSESSMENT_REQUIRED';end if;
 select *into r from ac_dce_certificate_requests where attempt_id=a.id;if found then return jsonb_build_object('received',true,'id',r.id,'reference',r.reference,'status',r.status,'reused',true);end if;
 if coalesce((p_details->>'consent')::boolean,false)is not true or length(coalesce(p_details->>'learnerName',''))not between 2 and 160 or length(coalesce(p_details->>'requesterName',''))not between 2 and 160 or coalesce(p_details->>'email','')!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'or coalesce(p_details->>'contactLocale','')not in('ar','fr','en')then raise exception'REQUEST_DETAILS_REQUIRED';end if;
 insert into ac_dce_certificate_requests(reference,course_id,release_id,attempt_id,locale,subject_hash,course_title,learner_name,requester_name,email,phone,contact_locale,evidence,policy,data,due_at,tenant_id,territory_id)values('AC-CERT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16)),a.course_id,z.id,a.id,a.locale,a.subject_hash,z.manifest->>'title',p_details->>'learnerName',p_details->>'requesterName',lower(p_details->>'email'),left(coalesce(p_details->>'phone',''),60),p_details->>'contactLocale',a.evidence||jsonb_build_object('level',a.evidence_level,'score',a.score,'completed',a.completed),policy,jsonb_build_object('consent',true,'receivedAt',now(),'communication',jsonb_build_object('state','not_attempted')),now()+make_interval(days=>greatest(1,least(365,coalesce((policy->>'followUpDays')::int,3)))),p_tenant,p_territory)returning *into r;
 insert into ac_dce_certificate_history(request_id,actor_id,action,data)values(r.id,p_actor,'received',jsonb_build_object('releaseId',z.id,'attemptId',a.id));reply:=jsonb_build_object('received',true,'reference',r.reference,'id',r.id,'status',r.status,'notificationDelivery','not_attempted');insert into ac_dce_commands values(p_request,p_actor,p_hash,reply,now());return reply;
end $$;
create or replace function public.ac_dce_r5_certificate_action(p_actor text,p_tenant text,p_territory text,p_request uuid,p_hash text,p_id uuid,p_revision int,p_action text,p_data jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare r ac_dce_certificate_requests;c ac_dce_commands;reply jsonb;next_state text;case_id uuid;begin
 perform pg_advisory_xact_lock(hashtextextended(p_actor||p_request::text,0));select *into c from ac_dce_commands where actor_id=p_actor and request_id=p_request;if found then if c.input_hash<>p_hash then raise exception'IDEMPOTENCY_CONFLICT';end if;return c.response;end if;
 select *into r from ac_dce_certificate_requests where id=p_id and tenant_id is not distinct from p_tenant and territory_id is not distinct from p_territory for update;if not found then raise exception'NOT_FOUND';end if;if r.revision<>p_revision then raise exception'REVISION_CONFLICT';end if;next_state:=r.status;
 if p_action='prepare_document_case'then
 if nullif(r.data->>'privateCaseId','')is null then insert into ac_dce_records(kind,key,title,audience,data,lifecycle,created_by,updated_by,tenant_id,territory_id)values('case','certificate-document-'||r.id::text,r.reference||' · '||r.course_title,'parent',jsonb_build_object('source','explicit_certificate_request','certificateRequestId',r.id,'experienceId',r.course_id,'releaseId',r.release_id,'body','Private certificate preparation.','notes','[]'::jsonb),'open',p_actor,p_actor,p_tenant,p_territory)returning id into case_id;r.data:=r.data||jsonb_build_object('privateCaseId',case_id);end if;
 elsif p_action='assign'then
 if nullif(p_data->>'assignedTo','')is not null and not exists(select 1 from app_users where id::text=p_data->>'assignedTo'and status='active')then raise exception'STAFF_REQUIRED';end if;r.assigned_to:=nullif(p_data->>'assignedTo','');
 elsif p_action in('note','contact','follow_up')then
 if length(coalesce(p_data->>'body',''))not between 3 and 4000 then raise exception'NOTE_REQUIRED';end if;if p_action='follow_up'then r.due_at:=nullif(p_data->>'dueAt','')::timestamptz;if r.due_at is null then raise exception'FOLLOW_UP_DATE_REQUIRED';end if;end if;
 elsif p_action='review'and r.status in('new','awaiting_information')then next_state:='review';
 elsif p_action='awaiting_information'and r.status in('new','review')then next_state:='awaiting_information';
 elsif p_action='approve'and r.status in('new','review','awaiting_information')then next_state:='approved';
 elsif p_action='reject'and r.status in('new','review','awaiting_information','approved')then next_state:='rejected';
 elsif p_action='cancel'and r.status not in('issued','closed')then next_state:='cancelled';
 elsif p_action='issue'and r.status='approved'then
 if nullif(p_data->>'documentId','')is null or length(coalesce(p_data->>'issuer',''))<2 then raise exception'ISSUED_DOCUMENT_REQUIRED';end if;next_state:='issued';r.issued_at:=now();r.issued_by:=p_actor;r.data:=r.data||jsonb_build_object('issuedDocument',p_data);
 elsif p_action='replace'and r.status in('issued','closed')then
 if nullif(p_data->>'documentId','')is null or length(coalesce(p_data->>'body',''))<12 then raise exception'REPLACEMENT_REASON_REQUIRED';end if;r.data:=r.data||jsonb_build_object('issuedDocument',p_data,'previousDocuments',coalesce(r.data->'previousDocuments','[]')||jsonb_build_array(r.data->'issuedDocument'));
 elsif p_action='close'and r.status in('issued','rejected','cancelled')then next_state:='closed';
 elsif p_action='reopen'and r.status in('closed','rejected','cancelled')then next_state:=case when r.issued_at is not null then'issued'else'review'end;
 else raise exception'INVALID_CERTIFICATE_TRANSITION';end if;
 if p_action in('reject','cancel','reopen','awaiting_information')and length(coalesce(p_data->>'body',''))<3 then raise exception'DECISION_REASON_REQUIRED';end if;
 update ac_dce_certificate_requests set status=next_state,assigned_to=r.assigned_to,due_at=r.due_at,data=r.data,issued_at=r.issued_at,issued_by=r.issued_by,revision=revision+1,updated_at=now()where id=r.id returning *into r;
 insert into ac_dce_certificate_history(request_id,actor_id,action,data)values(r.id,p_actor,p_action,p_data);reply:=jsonb_build_object('request',to_jsonb(r),'receipt',p_request);insert into ac_dce_commands values(p_request,p_actor,p_hash,reply,now());return reply;
end $$;
do $$declare n text;f regprocedure;begin
 foreach n in array array['ac_dce_editions','ac_dce_assessment_attempts','ac_dce_certificate_requests','ac_dce_certificate_history']loop execute format('comment on table public.%I is %L',n,'ANGELCARE_DCE_AUTONOMOUS_R5');execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select,insert,update,delete on public.%I to service_role',n);end loop;
 for f in select oid::regprocedure from pg_proc where pronamespace='public'::regnamespace and proname like'ac_dce_r5_%'loop execute format('comment on function %s is %L',f,'ANGELCARE_DCE_AUTONOMOUS_R5');execute format('revoke all on function %s from public,anon,authenticated',f);execute format('grant execute on function %s to service_role',f);end loop;
end $$;
notify pgrst,'reload schema';commit;
